<script setup lang="ts">
import QRCode from 'qrcode'
definePageMeta({layout:'custom'})
const {t}=useI18n(),route=useRoute(),{bizErrorMessage}=useBizError()
const records=ref<any[]>([]),record=computed(()=>records.value[0]),error=ref(''),loading=ref(true),copies=ref(1),offset=ref(0)
const maxCopies=computed(()=>Math.max(1,Math.floor(100/Math.max(1,records.value.length))))
const valid=computed(()=>Number.isInteger(copies.value)&&copies.value>=1&&copies.value<=maxCopies.value&&Number.isInteger(offset.value)&&offset.value>=0&&offset.value<=9)
const pages=computed(()=>{if(!valid.value)return [];const labels:any[]=[...Array(offset.value).fill(null),...records.value.flatMap(row=>Array(copies.value).fill(row))];return Array.from({length:Math.ceil(labels.length/10)},(_,index)=>labels.slice(index*10,index*10+10))})
const barcodeValid=(row:any)=>row?.code&&/^[\x20-\x7E]+$/.test(row.code)
const fontSize=(row:any)=>Math.max(14,Math.min(50,210/Math.max(1,String(row?.code||'').length)*1.5))+'px'
const locationPath=(row:any)=>{const parts=String(row?.code||'').split('-');return parts.length===3&&parts.every(Boolean)?`ZONE ${parts[0]} · RACK ${parts[1]} · LEVEL ${parts[2]}`:parts.length===2&&parts.every(Boolean)?`ZONE ${parts[0]} · BAY ${parts[1]}`:''}
const print=async()=>{if(loading.value||!records.value.length||!valid.value||error.value)return;await document.fonts.ready;await nextTick();if(!loading.value&&records.value.length&&valid.value&&!error.value)window.print()}
let generation=0
const load=async()=>{
 const seq=++generation;records.value=[];error.value='';loading.value=true
 const ids=[...new Set(String(route.query.ids||route.params.id).split(',').map(Number))]
 if(!ids.length||ids.length>100||ids.some(id=>!Number.isInteger(id)||id<=0)){error.value=t('location-label.invalid');loading.value=false;return}
 const result=[]
 for(const id of ids){const row=await httpRequest<any>('/api/warehouse/location/'+id,{onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}});if(seq!==generation)return;if(!row){loading.value=false;return}try{row.qr=await QRCode.toDataURL(row.code,{errorCorrectionLevel:'M',margin:4,width:416})}catch{error.value=t('location-label.code-error');loading.value=false;return}if(seq!==generation)return;result.push(row)}
 records.value=result;loading.value=false
}
watch(()=>[route.params.id,route.query.ids],load,{immediate:true})
onBeforeUnmount(()=>generation++)
useHead({title:()=>t('location-label.title')+' · '+(record.value?.code||'')})
</script>
<template><div class="w-location-label-print w-scope"><div class="toolbar"><NuxtLink class="w-label-back" :to="'/location/detail/'+route.params.id">{{record?.code||t('nav.location')}}</NuxtLink><span class="paper-type">A4 · 10 × 99.1 × 57 mm</span><WField :label="t('location-label.copies')"><WInput v-model.number="copies" type="number" min="1" :max="maxCopies"/></WField><WField :label="t('location-label.offset')"><WSelect v-model="offset" :options="Array.from({length:10},(_,value)=>({value,label:String(value+1)}))"/></WField><WButton icon="printer" :disabled="loading||!records.length||!valid||!!error" @click="print">{{t('button.print-to-pdf')}}</WButton></div><WAlert v-if="error" tone="block" :title="error"><template #actions><WButton :disabled="loading" @click="load">{{t('dn.list.retry')}}</WButton></template></WAlert><WAlert v-if="!valid" tone="block" :title="t('location-label.invalid')"/><WEmptyState v-if="loading" :title="t('common.status.loading')"/><p class="hint">{{t('location-label.hint')}}</p><div v-if="records.length" class="paper-scroll"><section v-for="(page,index) in pages" :key="index" class="label-sheet" :aria-label="`${record.code} · ${index+1}/${pages.length}`"><div v-for="(label,slot) in page" :key="slot" class="label" :class="{blank:!label,'long-code':label&&String(label.code).length>20}"><template v-if="label"><header><span>{{label.warehouse?.name||label.warehouse_name}}</span><b v-if="label.location_type!=='standard'">{{label.location_type==='damaged'?'DAMAGED':'RETURNS'}} {{t('common.locations.'+label.location_type)}}</b><span v-else class="location-path">{{locationPath(label)}}</span></header><div class="code-block"><strong class="code" :style="{fontSize:fontSize(label)}">{{label.code}}</strong><small v-if="label.location_type!=='standard'" class="location-path">{{locationPath(label)}}</small></div><img class="qr" :src="label.qr" :alt="'QR '+label.code"/><Barcode v-if="barcodeValid(label)" class="code128" :id="`label-${index}-${slot}`" :value="label.code" :options="{displayValue:false,width:1.2,height:40,margin:10}"/><small v-else class="unicode-code">{{label.code}}</small></template></div></section></div></div></template>
<style scoped>
.w-location-label-print{min-height:100vh;padding:24px;background:#F6F7FA;color:#151923}.toolbar{display:flex;align-items:end;flex-wrap:wrap;gap:16px;max-width:1000px;margin:0 auto 16px}.w-label-back{color:#5F1FE6;text-decoration:none;font-size:14px;font-weight:500;align-self:center}.paper-type{font-size:12px;line-height:18px;color:#656C7A;align-self:center;margin-right:auto}.toolbar>.w-field{width:110px}.hint{font-size:12px;line-height:18px;color:#656C7A;max-width:794px;margin:0 auto 16px}.paper-scroll{overflow:auto}.label-sheet{box-sizing:border-box;width:210mm;height:297mm;background:white;padding:6mm 4.65mm;display:grid;grid-template-columns:repeat(2,99.1mm);grid-template-rows:repeat(5,57mm);column-gap:2.5mm;margin:0 auto 24px;font-family:Inter,'Noto Sans SC','Noto Sans JP',sans-serif;line-height:1.25}.label{box-sizing:border-box;border:1px dashed #CDD1DA;border-radius:10px;padding:13px 15px 12px;display:grid;grid-template-columns:minmax(0,1fr) 104px;grid-template-rows:auto minmax(0,1fr) auto;column-gap:12px;overflow:hidden}.label.blank{border-color:transparent}.label header{grid-column:1/-1;display:flex;justify-content:space-between;gap:8px;align-items:center;padding-bottom:6px;border-bottom:1px solid #151923;font-size:9px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;overflow-wrap:anywhere}.label header b{border:1.5px solid #151923;padding:1px 6px;letter-spacing:.08em}.code{align-self:center;font-weight:900;letter-spacing:.01em;line-height:1;overflow-wrap:anywhere;font-variant-numeric:tabular-nums;min-width:0}.qr{grid-row:2/4;grid-column:2;align-self:center;display:block;width:104px;height:104px;image-rendering:pixelated}.code128{grid-row:3;grid-column:1;max-width:100%;height:48px}.unicode-code{font-size:10px;overflow-wrap:anywhere}@media(max-width:820px){.w-location-label-print{padding:16px}.label-sheet{margin-left:0}.toolbar{gap:12px}}@media print{.w-location-label-print{padding:0;background:white}.toolbar,.hint,.w-alert{display:none}.paper-scroll{overflow:visible}.label-sheet{margin:0;break-after:page}.label-sheet:last-child{break-after:auto}.label{break-inside:avoid;border-color:transparent}}
</style>
<style>@page{size:A4;margin:0;@bottom-right{content:none}}@media print{html,body{margin:0!important;padding:0!important;background:white!important}.nuxt-devtools-panel,.nuxt-devtools-toggle{display:none!important}}</style>

<style scoped>.code-block{align-self:center;min-width:0;display:flex;flex-direction:column;gap:5px}.location-path{font-size:8px;font-weight:600;letter-spacing:0;overflow-wrap:anywhere}.label header>span:first-child{min-width:0}.label header b{flex:none;font-size:8px}</style>

<style scoped>.label.long-code .qr{grid-row:2;width:88px;height:88px;justify-self:center}.label.long-code .code128{grid-column:1/-1;width:100%;height:42px}</style>
